_STYLES={
'%':(PercentStyle,BASIC_FORMAT),
'{':(StrFormatStyle,'{levelname}:{name}:{message}'),
'$':(StringTemplateStyle,'\\\${levelname}:\\\${name}:\\\${message}'),
}

